/* Compare a class name (NUL-terminated) against a target type name (ptr,len),
 * both truncated at the first '$' so a generic specialization like
 * "Vector$f64" matches the base name "Vector". Backs the string form of
 * is_a? used by synthesized operator-overload dispatchers. */
static int w_typename_base_eq(const char *cls_name, const char *tn, size_t tn_len) {
    size_t i = 0;
    while (1) {
        char ca = cls_name[i];
        char cb = (i < tn_len) ? tn[i] : '\0';
        if (ca == '$') ca = '\0';
        if (cb == '$') cb = '\0';
        if (ca != cb) return 0;
        if (ca == '\0') return 1;
        i++;
    }
}

static int w_type_name_eq_lit(const char *tn, size_t tn_len, const char *lit) {
    size_t i = 0;
    while (lit[i]) {
        if (i >= tn_len || tn[i] != lit[i]) return 0;
        i++;
    }
    return i == tn_len;
}

static int w_primitive_is_a_type_name(WValue recv, const char *tn, size_t tn_len) {
    if (w_is_nil(recv))
        return w_type_name_eq_lit(tn, tn_len, "Nil");
    if (w_is_range(recv) || w_is_range_imm(recv))
        return w_type_name_eq_lit(tn, tn_len, "Range");
    if (is_duration_any(recv))
        return w_type_name_eq_lit(tn, tn_len, "Duration");
    if (w_is_date(recv))
        return w_type_name_eq_lit(tn, tn_len, "Date");
    if (w_is_instant(recv))
        return w_type_name_eq_lit(tn, tn_len, "Instant");
    if (w_is_bytes(recv) && w_type_name_eq_lit(tn, tn_len, "ByteArray"))
        return 1;
    if (w_is_small_array(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "SmallArray") ||
               w_type_name_eq_lit(tn, tn_len, "Array");
    }
    if (w_is_big_array(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "BigArray") ||
               w_type_name_eq_lit(tn, tn_len, "Array");
    }
    if (w_is_char(recv)) {
        if (w_type_name_eq_lit(tn, tn_len, "Codepoint")) return 1;
        if (w_type_name_eq_lit(tn, tn_len, "Char")) return w_char_is_ascii(recv);
        return 0;
    }
    if (w_is_color(recv))
        return w_type_name_eq_lit(tn, tn_len, "Color");
    if (w_is_ipv4(recv))
        return w_type_name_eq_lit(tn, tn_len, "IPv4");
    if (w_is_ipv6(recv))
        return w_type_name_eq_lit(tn, tn_len, "IPv6");
    if (w_is_mac(recv))
        return w_type_name_eq_lit(tn, tn_len, "MAC");
    if (w_is_obj(recv) && w_subtag(recv) == W_SUBTAG_UUID)
        return w_type_name_eq_lit(tn, tn_len, "UUID");
    if (w_is_closure(recv))
        return w_type_name_eq_lit(tn, tn_len, "Closure");
    if (w_is_strbuf(recv))
        return w_type_name_eq_lit(tn, tn_len, "StringBuffer");
    if (is_currency_any(recv))
        return w_type_name_eq_lit(tn, tn_len, "Currency");
    if (is_quantity_any(recv))
        return w_type_name_eq_lit(tn, tn_len, "Quantity");
    if (w_is_rational_any(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "Rational") ||
               w_type_name_eq_lit(tn, tn_len, "Real") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    if (w_is_complex(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "Complex") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    if (w_is_int(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "Int") ||
               w_type_name_eq_lit(tn, tn_len, "Integer") ||
               w_type_name_eq_lit(tn, tn_len, "Real") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    if (w_is_bigint(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "BigInt") ||
               w_type_name_eq_lit(tn, tn_len, "Int") ||
               w_type_name_eq_lit(tn, tn_len, "Integer") ||
               w_type_name_eq_lit(tn, tn_len, "Real") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    if (w_is_double(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "Float") ||
               w_type_name_eq_lit(tn, tn_len, "Real") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    if (is_decimal_any(recv)) {
        return w_type_name_eq_lit(tn, tn_len, "Decimal") ||
               w_type_name_eq_lit(tn, tn_len, "Real") ||
               w_type_name_eq_lit(tn, tn_len, "Number");
    }
    return 0;
}

/* Runtime ancestry primitive shared by public is_a? and compiler-generated
 * typed-overload gates. Keeping the gate callable directly avoids hashing and
 * looking up `is_a?` for every overloaded operator invocation. */
WValue w_value_is_a(WValue recv, WValue target) {
    /* Class-object target: walk instance ancestry by class_id. */
    if (__builtin_expect(w_is_class(target), 1)) {
        WClass *tc = (WClass *)w_as_ptr(target);
        if (w_is_instance(recv)) {
            WClass *k = g_class_table[((WObject *)w_as_ptr(recv))->class_id];
            while (k) {
                if (k->class_id == tc->class_id) return W_TRUE;
                k = k->superclass;
            }
            return W_FALSE;
        }
        if (w_is_class(recv)) return W_FALSE;
        const char *tn = tc->name;
        if (w_is_int(recv)) {
            if (tn[0] == 'I' && tn[1] == 'n' && tn[2] == 't') {
                if (tn[3] == '\0' || (tn[3] == 'e' && tn[4] == 'g' && tn[5] == 'e' && tn[6] == 'r' && tn[7] == '\0'))
                    return W_TRUE;
            }
            if (tn[0] == 'R' && strcmp(tn, "Real") == 0) return W_TRUE;
            if (tn[0] == 'N' && strcmp(tn, "Number") == 0) return W_TRUE;
            return W_FALSE;
        }
        if (w_is_array(recv)) {
            if (w_is_bytes(recv) && strcmp(tn, "ByteArray") == 0) return W_TRUE;
            return w_bool(tn[0] == 'A' && tn[1] == 'r' && tn[2] == 'r' && tn[3] == 'a' && tn[4] == 'y' && tn[5] == '\0');
        }
        if (w_is_double(recv)) {
            if (tn[0] == 'F' && strcmp(tn, "Float") == 0) return W_TRUE;
            if (tn[0] == 'R' && strcmp(tn, "Real") == 0) return W_TRUE;
            if (tn[0] == 'N' && strcmp(tn, "Number") == 0) return W_TRUE;
            return W_FALSE;
        }
        if (w_is_string(recv) || w_is_rope(recv)) {
            return w_bool(tn[0] == 'S' && strcmp(tn, "String") == 0);
        }
        const char *pn =
            w_is_symbol(recv) ? "Symbol" :
            (w_is_body(recv) || w_is_wire_sequence(recv)) ? "Array" :
            w_is_hash(recv) ? "Hash" :
            w_is_bool(recv) ? "Boolean" : NULL;
        return w_bool((pn && strcmp(pn, tn) == 0) ||
                      w_primitive_is_a_type_name(recv, tn, strlen(tn)));
    }

    /* String target: compare generic specializations by base name. Resolve
     * instances first — the hot overload-gate path — before probing primitive
     * tags or constructing a primitive type name. Read ropes into a stack
     * buffer (never w_rope_flatten) so w_value_is_a preserves memory(read). */
    if (w_is_stringy(target) || w_is_rope(target)) {
        char sbuf[128];
        const char *tn;
        size_t tn_len;
        if (w_is_rope(target)) {
            uint32_t rlen = w_rope_len(target);
            if (rlen >= sizeof(sbuf)) return w_bool(0);
            uint32_t pos = 0;
            w_rope_write(target, sbuf, &pos);
            sbuf[pos] = '\0';
            tn = sbuf;
            tn_len = pos;
        } else {
            w_str_data(target, sbuf, &tn, &tn_len);
        }
        if (w_is_instance(recv)) {
            WClass *k = g_class_table[((WObject *)w_as_ptr(recv))->class_id];
            while (k) {
                if (w_typename_base_eq(k->name, tn, tn_len)) return w_bool(1);
                k = k->superclass;
            }
            return w_bool(0);
        }
        if (w_is_class(recv))
            return w_bool(w_typename_base_eq(((WClass *)w_as_ptr(recv))->name, tn, tn_len));
        const char *pn =
            w_is_int(recv) ? "Int" :
            w_is_double(recv) ? "Float" :
            (w_is_string(recv) || w_is_rope(recv)) ? "String" :
            w_is_symbol(recv) ? "Symbol" :
            (w_is_array(recv) || w_is_body(recv) || w_is_wire_sequence(recv)) ? "Array" :
            w_is_hash(recv) ? "Hash" :
            w_is_bool(recv) ? "Boolean" : NULL;
        return w_bool((pn && w_typename_base_eq(pn, tn, tn_len)) ||
                      w_primitive_is_a_type_name(recv, tn, tn_len));
    }
    return w_bool(0);
}

