/* Array count, find_index/index, last_index, replace_byte!, delete_at.
 * These keep the typed-array SIMD fast paths the cascade had. */
static WValue w_ic_array_count(WValue r, WValue *a, int c) {
    WArray *arr = as_array(r);
    if (c >= 1 && w_is_closure(a[c - 1])) {
        WClosure *cl = as_closure(a[c - 1]);
        int64_t n = 0;
        if (arr->ebits == 65) {
            const WValue *slots = arr->slots + arr->start;
            for (int32_t i = 0; i < arr->size; i++)
                if (w_truthy(call_closure_1(cl, slots[i]))) n++;
        } else {
            for (int32_t i = 0; i < arr->size; i++)
                if (w_truthy(call_closure_1(cl, w_rt_array_slot_load_decoded(arr, i)))) n++;
        }
        return w_int(n);
    }
    if (c >= 1) {
        if (arr->ebits == 1 && (a[0] == W_TRUE || a[0] == W_FALSE) && (arr->start & 7) == 0) {
            int64_t set_bits = w_u1_count_set((const uint8_t *)arr->slots + (arr->start >> 3), arr->size);
            return w_int(a[0] == W_TRUE ? set_bits : (arr->size - set_bits));
        }
        if (arr->ebits == 65) {
            return w_int(w_array_count_eq_w64(arr->slots + arr->start, arr->size, a[0]));
        }
        if (w_is_int(a[0])) {
            int64_t needle = w_as_int(a[0]);
            if (arr->ebits == 8 && needle >= 0 && needle <= 255)
                return w_int(w_byte_scan_count_threaded((const uint8_t *)arr->slots + arr->start,
                                                        arr->size, (uint8_t)needle));
            if (arr->ebits == 16 && needle >= 0 && needle <= UINT16_MAX)
                return w_int(w_u16_scan_count_threaded((const uint16_t *)arr->slots + arr->start,
                                                       arr->size, (uint16_t)needle));
            if (arr->ebits == 32 && needle >= 0 && needle <= UINT32_MAX)
                return w_int(w_u32_scan_count_threaded((const uint32_t *)arr->slots + arr->start,
                                                       arr->size, (uint32_t)needle));
            if (arr->ebits == 33 && needle >= INT32_MIN && needle <= INT32_MAX)
                return w_int(w_u32_scan_count_threaded((const uint32_t *)arr->slots + arr->start,
                                                       arr->size, (uint32_t)needle));
        }
        int64_t n = 0;
        for (int32_t i = 0; i < arr->size; i++)
            if (w_eq(w_rt_array_slot_load_decoded(arr, i), a[0]) == W_TRUE) n++;
        return w_int(n);
    }
    return w_int(arr->size);
}
static WValue w_ic_array_find_index(WValue r, WValue *a, int c) {
    WArray *arr = as_array(r);
    if (c < 1) return W_NIL;
    if (w_is_closure(a[c - 1])) {
        WClosure *cl = as_closure(a[c - 1]);
        if (arr->ebits == 65) {
            const WValue *slots = arr->slots + arr->start;
            for (int32_t i = 0; i < arr->size; i++)
                if (w_truthy(call_closure_1(cl, slots[i]))) return w_int(i);
        } else {
            for (int32_t i = 0; i < arr->size; i++)
                if (w_truthy(call_closure_1(cl, w_rt_array_slot_load_decoded(arr, i)))) return w_int(i);
        }
        return W_NIL;
    }
    if (arr->ebits == 1 && (a[0] == W_TRUE || a[0] == W_FALSE) && (arr->start & 7) == 0) {
        int64_t idx = (a[0] == W_TRUE)
            ? w_u1_index_set((const uint8_t *)arr->slots + (arr->start >> 3), arr->size)
            : w_u1_index_unset((const uint8_t *)arr->slots + (arr->start >> 3), arr->size);
        return idx < 0 ? W_NIL : w_int(idx);
    }
    if (arr->ebits == 65) {
        int64_t idx = w_array_scan_eq_w64(arr->slots + arr->start, arr->size, a[0], 0);
        return idx < 0 ? W_NIL : w_int(idx);
    }
    if (w_is_int(a[0])) {
        int64_t needle = w_as_int(a[0]);
        if (arr->ebits == 8 && needle >= 0 && needle <= 255) {
            int64_t idx = w_byte_scan_eq_threaded((const uint8_t *)arr->slots + arr->start,
                                                  arr->size, (uint8_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 16 && needle >= 0 && needle <= UINT16_MAX) {
            int64_t idx = w_u16_scan_eq_threaded((const uint16_t *)arr->slots + arr->start,
                                                 arr->size, (uint16_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 32 && needle >= 0 && needle <= UINT32_MAX) {
            int64_t idx = w_u32_scan_eq_threaded((const uint32_t *)arr->slots + arr->start,
                                                 arr->size, (uint32_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 33 && needle >= INT32_MIN && needle <= INT32_MAX) {
            int64_t idx = w_u32_scan_eq_threaded((const uint32_t *)arr->slots + arr->start,
                                                 arr->size, (uint32_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
    }
    for (int32_t i = 0; i < arr->size; i++)
        if (w_eq(w_rt_array_slot_load_decoded(arr, i), a[0]) == W_TRUE) return w_int(i);
    return W_NIL;
}
static WValue w_ic_array_last_index(WValue r, WValue *a, int c) {
    if (c < 1) return W_NIL;
    WArray *arr = as_array(r);
    if (arr->ebits == 65) {
        int64_t idx = w_array_scan_eq_w64(arr->slots + arr->start, arr->size, a[0], 1);
        return idx < 0 ? W_NIL : w_int(idx);
    }
    if (w_is_int(a[0])) {
        int64_t needle = w_as_int(a[0]);
        if (arr->ebits == 8 && needle >= 0 && needle <= 255) {
            int64_t idx = w_byte_scan_eq_rev((const uint8_t *)arr->slots + arr->start,
                                              arr->size, (uint8_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 16 && needle >= 0 && needle <= UINT16_MAX) {
            int64_t idx = w_u16_scan_eq_rev((const uint16_t *)arr->slots + arr->start,
                                             arr->size, (uint16_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 32 && needle >= 0 && needle <= UINT32_MAX) {
            int64_t idx = w_u32_scan_eq_rev((const uint32_t *)arr->slots + arr->start,
                                             arr->size, (uint32_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
        if (arr->ebits == 33 && needle >= INT32_MIN && needle <= INT32_MAX) {
            int64_t idx = w_u32_scan_eq_rev((const uint32_t *)arr->slots + arr->start,
                                             arr->size, (uint32_t)needle);
            return idx < 0 ? W_NIL : w_int(idx);
        }
    }
    for (int32_t i = arr->size - 1; i >= 0; i--)
        if (w_eq(w_rt_array_slot_load_decoded(arr, i), a[0]) == W_TRUE) return w_int(i);
    return W_NIL;
}
static WValue w_ic_array_replace_byte(WValue r, WValue *a, int c) {
    if (c < 2) die("replace_byte! requires 2 arguments");
    WArray *arr = as_array(r);
    if ((arr->flags & W_FLAG_OWNED) == 0)
        w_raise(w_string("replace_byte!: cannot mutate a borrowed view"));
    if (arr->ebits == 8 && w_is_int(a[0]) && w_is_int(a[1])) {
        int64_t old_b = w_as_int(a[0]);
        int64_t new_b = w_as_int(a[1]);
        if (old_b >= 0 && old_b <= 255 && new_b >= 0 && new_b <= 255) {
            int64_t n = w_byte_replace((uint8_t *)arr->slots + arr->start,
                                        arr->size, (uint8_t)old_b, (uint8_t)new_b);
            return w_int(n);
        }
    }
    w_raise(w_string("replace_byte!: only valid on u8 arrays with byte arguments [0,255]"));
    return W_NIL;
}
static WValue w_array_delete_at_fast(WValue r, int64_t idx) {
    WArray *arr = as_array(r);
    int64_t n = arr->size;
    if (idx < 0) idx += n;
    if (idx < 0 || idx >= n) return W_NIL;
    WValue removed = w_rt_array_slot_load_decoded(arr, idx);
    int64_t tail = n - 1 - idx;
    if (tail > 0) {
        if (arr->ebits == 65) {
            WValue *p = arr->slots + arr->start + idx;
            memmove(p, p + 1, (size_t)tail * sizeof(WValue));
        } else {
            int64_t bits = array_storage_bits(arr->ebits);
            if (bits >= 8) {
                size_t elem_sz = (size_t)(bits / 8);
                uint8_t *p = (uint8_t *)arr->slots + (size_t)(arr->start + idx) * elem_sz;
                memmove(p, p + elem_sz, (size_t)tail * elem_sz);
            } else {
                for (int64_t i = idx; i < n - 1; i++)
                    w_array_set(r, w_int(i), w_rt_array_slot_load_decoded(arr, i + 1));
            }
        }
    }
    arr->size--;
    return removed;
}

/* Array storage iterator and the leaf collection ops that remain native. */
static WValue w_ic_array_each(WValue r, WValue *a, int c) {
    if (c < 1 || !w_is_closure(a[c - 1])) die("each requires a block");
    WClosure *cl = as_closure(a[c - 1]);
    WArray *arr = as_array(r);
    if (arr->ebits == 65) {
        for (int32_t i = 0; i < arr->size; i++)
            call_closure_1(cl, arr->slots[arr->start + i]);
    } else {
        for (int32_t i = 0; i < arr->size; i++)
            call_closure_1(cl, w_rt_array_slot_load_decoded(arr, i));
    }
    return r;
}
