/* Closed-world direct-tag dispatch for dynamic [], []=, size, push when
 * Array/Hash(/String) have not been reopened. Eliminates %__mcall_args stack
 * spills and polymorphic IC lookups on the hot builtin receiver tags, while
 * preserving exact fallback semantics for all other receivers (including
 * String, Range, Mmap, BigArray, SmallArray, Symbol, and user classes). */
WValue w_fast_idx_get(WValue recv, WValue key, WInlineCache *cache) {
    if (__builtin_expect(w_is_array(recv), 1)) {
        if (__builtin_expect(w_is_int(key), 1)) {
            WArray *a = w_as_array(recv);
            int64_t i = w_as_int(key);
            if (i < 0) i += a->size;
            if (__builtin_expect((uint64_t)i >= (uint64_t)a->size, 0)) return W_NIL;
            if (__builtin_expect(a->ebits == 65, 1)) return a->slots[a->start + i];
            return w_rt_array_slot_load_decoded(a, i);
        }
        return w_fast_idx_get_fallback(recv, key, cache);
    }
    if (__builtin_expect(w_is_hash(recv), 1)) {
        WHash *hash = (WHash *)w_as_ptr(recv);
        int64_t dense = w_hash_probe(hash, key);
        return dense < 0 ? W_NIL : hash->values[dense];
    }
    if (w_is_body(recv)) {
        if (__builtin_expect(w_is_int(key), 1)) {
            uint32_t len = w_unbox_body_length(recv);
            int64_t i = w_as_int(key);
            if (i < 0) i += len;
            if (i < 0 || (uint32_t)i >= len) return W_NIL;
            return w_body_arena_get(w_unbox_body_offset(recv), (uint32_t)i);
        }
        return w_fast_idx_get_fallback(recv, key, cache);
    }
    if (w_is_wire(recv)) {
        if (w_is_wire_sequence(recv)) {
            if (!w_is_int(key)) return W_NIL;
            return w_wire_sequence_get(recv, w_as_int(key));
        }
        return w_wire_field_load_inline(recv, key, W_NIL);
    }
    return w_fast_idx_get_fallback(recv, key, cache);
}

WValue w_fast_idx_set(WValue recv, WValue key, WValue val, WInlineCache *cache) {
    if (__builtin_expect(w_is_hash(recv), 1)) {
        return w_hash_set(recv, key, val);
    }
    if (__builtin_expect(w_is_array(recv), 1)) {
        if (__builtin_expect(w_is_int(key), 1)) {
            WArray *a = w_as_array(recv);
            int64_t i = w_as_int(key);
            if (i < 0) i += a->size;
            if (__builtin_expect(a->ebits == 65 && (uint64_t)i < (uint64_t)a->size, 1)) {
                a->slots[a->start + i] = val;
                return val;
            }
            return w_array_set(recv, key, val);
        }
        return w_fast_idx_set_fallback(recv, key, val, cache);
    }
    if (w_is_wire(recv)) {
        if (!w_is_wire_sequence(recv))
            return w_wire_field_store(recv, key, val);
        if (w_is_int(key))
            return w_wire_sequence_set(recv, w_as_int(key), val);
    }
    return w_fast_idx_set_fallback(recv, key, val, cache);
}

WValue w_fast_size(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(w_is_array(recv), 1))
        return w_box_int((int64_t)w_as_array(recv)->size);
    if (__builtin_expect(w_is_hash(recv), 1))
        return w_box_int((int64_t)((WHash *)w_as_ptr(recv))->count);
    if (__builtin_expect(w_is_string(recv), 1)) {
        uint64_t sm = (recv >> 1) & 7ULL;
        if (sm <= 5ULL) return w_box_int((int64_t)sm);
        if (sm == 6ULL) {
            uint64_t sc = (recv >> 28) & 63ULL;
            if (sc != 0ULL) return w_box_int((int64_t)sc);
        }
        return w_int(w_string_byte_length(recv));
    }
    if (w_is_body(recv))
        return w_box_int((int64_t)w_unbox_body_length(recv));
    if (w_is_wire_sequence(recv))
        return w_box_int((int64_t)w_wire_sequence_size(recv));
    if (w_is_rope(recv))
        return w_box_int((int64_t)w_rope_len(recv));
    return w_fast_size_fallback(recv, cache);
}

WValue w_fast_push(WValue recv, WValue val, WInlineCache *cache) {
    if (__builtin_expect(w_is_array(recv), 1)) {
        WArray *a = w_as_array(recv);
        int32_t idx = a->start + a->size;
        if (__builtin_expect(a->ebits == 65 && idx < a->cap && (a->flags & W_FLAG_OWNED) != 0, 1)) {
            a->slots[idx] = val;
            a->size++;
            return recv;
        }
        return w_array_push(recv, val);
    }
    return w_fast_push_fallback(recv, val, cache);
}

WValue w_fast_to_s(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv), 1)) return recv;
    if (__builtin_expect(w_is_int(recv), 1)) return w_int_to_str(w_as_int(recv));
    if (__builtin_expect(w_is_symbol(recv), 1)) return recv & ~(WValue)1;
    if (__builtin_expect(w_is_strbuf(recv), 0)) return w_strbuf_to_s(recv);
    if (__builtin_expect(w_is_rope(recv), 0)) return w_rope_flatten(recv);
    if (__builtin_expect(recv == W_NIL, 0)) return w_string("");
    if (__builtin_expect(w_is_bool(recv), 0)) return w_string(recv == W_TRUE ? "true" : "false");
    if (__builtin_expect(w_is_bigint(recv), 0)) return bigint_to_s_boxed(recv);
    return w_fast_to_s_fallback(recv, cache);
}

