WValue w_fast_empty(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(w_is_array(recv), 1))
        return w_as_array(recv)->size == 0 ? W_TRUE : W_FALSE;
    if (__builtin_expect(w_is_hash(recv), 1))
        return ((WHash *)w_as_ptr(recv))->count == 0 ? W_TRUE : W_FALSE;
    if (__builtin_expect(w_is_string(recv), 1)) {
        size_t mode = (size_t)((recv >> 1) & 7);
        if (mode <= 5) return mode == 0 ? W_TRUE : W_FALSE;
        char _b[6]; const char *s; size_t slen;
        w_str_data(recv, _b, &s, &slen);
        return slen == 0 ? W_TRUE : W_FALSE;
    }
    return w_fast_empty_fallback(recv, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_starts_with_fallback(WValue recv, WValue prefix, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_1_any(recv, WN_starts_with_q, prefix, cache);
}

WValue w_fast_starts_with(WValue recv, WValue prefix, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv) && w_is_string(prefix), 1)) {
        size_t rmode = (size_t)((recv >> 1) & 7);
        size_t pmode = (size_t)((prefix >> 1) & 7);
        if (pmode == 0) return W_TRUE;
        if (rmode <= 5) {
            if (pmode > rmode) return W_FALSE;
            uint64_t mask = (UINT64_C(1) << (8 * pmode)) - 1;
            return ((((recv ^ prefix) >> 4) & mask) == 0) ? W_TRUE : W_FALSE;
        }
        char _rb[6], _pb[6];
        const char *sd, *pd;
        size_t slen, plen;
        w_str_data(recv, _rb, &sd, &slen);
        w_str_data(prefix, _pb, &pd, &plen);
        if (plen > slen) return W_FALSE;
        return memcmp(sd, pd, plen) == 0 ? W_TRUE : W_FALSE;
    }
    return w_fast_starts_with_fallback(recv, prefix, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_ends_with_fallback(WValue recv, WValue suffix, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_1_any(recv, WN_ends_with_q, suffix, cache);
}

WValue w_fast_ends_with(WValue recv, WValue suffix, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv) && w_is_string(suffix), 1)) {
        size_t rmode = (size_t)((recv >> 1) & 7);
        size_t smode = (size_t)((suffix >> 1) & 7);
        if (smode == 0) return W_TRUE;
        if (rmode <= 5) {
            if (smode > rmode) return W_FALSE;
            uint64_t mask = (UINT64_C(1) << (8 * smode)) - 1;
            return ((((recv >> (4 + 8 * (rmode - smode))) ^ (suffix >> 4)) & mask) == 0) ? W_TRUE : W_FALSE;
        }
        char _rb[6], _sb[6];
        const char *sd, *pd;
        size_t slen, plen;
        w_str_data(recv, _rb, &sd, &slen);
        w_str_data(suffix, _sb, &pd, &plen);
        if (plen > slen) return W_FALSE;
        return memcmp(sd + slen - plen, pd, plen) == 0 ? W_TRUE : W_FALSE;
    }
    return w_fast_ends_with_fallback(recv, suffix, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_slice2_fallback(WValue recv, WValue start_v, WValue len_v, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_2_any(recv, WN_slice, start_v, len_v, cache);
}

WValue w_fast_slice2(WValue recv, WValue start_v, WValue len_v, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv) && w_is_int(start_v) && w_is_int(len_v), 1))
        return w_string_slice_raw(recv, w_as_int(start_v), w_as_int(len_v));
    if (__builtin_expect(w_is_array(recv) && w_is_int(start_v) && w_is_int(len_v), 1))
        return w_array_view(recv, start_v, len_v);
    return w_fast_slice2_fallback(recv, start_v, len_v, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_byte_at_fallback(WValue recv, WValue idx_v, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_1_any(recv, WN_byte_at, idx_v, cache);
}

WValue w_fast_byte_at(WValue recv, WValue idx_v, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv) && w_is_int(idx_v), 1)) {
        size_t mode = (size_t)((recv >> 1) & 7);
        int64_t i = w_as_int(idx_v);
        if (mode <= 5) {
            if (i < 0) i += (int64_t)mode;
            if ((uint64_t)i >= mode) return W_NIL;
            return W_TAG_INT | ((recv >> (4 + 8 * i)) & 0xFFULL);
        }
        char _b[6]; const char *s; size_t slen;
        w_str_data(recv, _b, &s, &slen);
        if (i < 0) i += (int64_t)slen;
        if (i < 0 || (size_t)i >= slen) return W_NIL;
        return W_TAG_INT | (uint64_t)(uint8_t)s[i];
    }
    return w_fast_byte_at_fallback(recv, idx_v, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_strip_fallback(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_0(recv, WN_strip, cache);
}

WValue w_fast_strip(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv), 1))
        return w_string_trim_ascii(recv, 1, 1);
    return w_fast_strip_fallback(recv, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_index_fallback(WValue recv, WValue arg, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_1_any(recv, WN_index, arg, cache);
}

WValue w_fast_index(WValue recv, WValue arg, WInlineCache *cache) {
    if (__builtin_expect(w_is_string(recv) && w_is_string(arg), 1))
        return w_string_index(recv, arg, W_NIL);
    if (__builtin_expect(w_is_array(recv), 1))
        return w_ic_array_find_index(recv, &arg, 1);
    return w_fast_index_fallback(recv, arg, cache);
}

__attribute__((noinline, cold))
static WValue w_fast_abs_fallback(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();
    return w_method_call_cached_0(recv, WN_abs, cache);
}

WValue w_fast_abs(WValue recv, WInlineCache *cache) {
    if (__builtin_expect(w_is_int(recv), 1)) {
        int64_t x = w_as_int(recv);
        return x < 0 ? w_box_int_checked(-x) : recv;
    }
    if (__builtin_expect(w_is_double(recv), 1))
        return w_box_double(fabs(w_as_double(recv)));
    return w_fast_abs_fallback(recv, cache);
}

/* Direct-call string builtins (bypass method dispatch) */

WValue w_string_count(WValue recv, WValue needle_v) {
    if (w_is_rope(recv)) recv = w_rope_flatten(recv);
    char _sbuf[6];
    const char *str;
    size_t str_len;
    w_str_data(recv, _sbuf, &str, &str_len);
    char _nbuf[6];
    const char *needle;
    size_t needle_len;
    w_str_data(needle_v, _nbuf, &needle, &needle_len);
    if (needle_len == 0 || needle_len > str_len) return w_int(0);
    if (needle_len == 1)
        return w_int(w_byte_scan_count_threaded((const uint8_t *)str, (int64_t)str_len, (uint8_t)needle[0]));
    int64_t count = 0;
#ifdef __aarch64__
    size_t limit = str_len - needle_len + 1;
    uint8_t first = (uint8_t)needle[0];
    uint8_t last = (uint8_t)needle[needle_len - 1];
    size_t i = 0;
    size_t next_allowed = 0;
    if (limit >= 16) {
        uint8x16_t v_first = vdupq_n_u8(first);
        uint8x16_t v_last = vdupq_n_u8(last);
        size_t end16 = limit - 16;
        while (i <= end16) {
            uint8x16_t vf = vld1q_u8((const uint8_t *)str + i);
            uint8x16_t vl = vld1q_u8((const uint8_t *)str + i + needle_len - 1);
            uint8x16_t eq = vandq_u8(vceqq_u8(vf, v_first), vceqq_u8(vl, v_last));
            if (vmaxvq_u8(eq) != 0) {
                uint8x8_t narrowed = vshrn_n_u16(vreinterpretq_u16_u8(eq), 4);
                uint64_t mask = vget_lane_u64(vreinterpret_u64_u8(narrowed), 0);
                while (mask != 0) {
                    int lane = __builtin_ctzll(mask) >> 2;
                    size_t pos = i + (size_t)lane;
                    if (pos >= next_allowed &&
                        (needle_len == 2 || memcmp(str + pos + 1, needle + 1, needle_len - 2) == 0)) {
                        count++;
                        next_allowed = pos + needle_len;
                    }
                    mask &= mask - 1;
                }
            }
            i += 16;
            if (next_allowed > i && next_allowed <= end16) i = next_allowed;
        }
    }
    if (i < next_allowed) i = next_allowed;
    while (i < limit) {
        if ((uint8_t)str[i] == first && (uint8_t)str[i + needle_len - 1] == last &&
            (needle_len == 2 || memcmp(str + i + 1, needle + 1, needle_len - 2) == 0)) {
            count++;
            i += needle_len;
        } else {
            i++;
        }
    }
#else
    const char *p = str;
    size_t rem = str_len;
    const char *hit;
    while ((hit = w_mem_search(p, rem, needle, needle_len)) != NULL) {
        count++;
        size_t adv = (size_t)(hit - p) + needle_len;
        p += adv;
        rem -= adv;
    }
#endif
    return w_int(count);
}

WValue w_string_index(WValue recv, WValue needle_v, WValue offset_v) {
    if (offset_v == W_NIL && ((recv & (W_TAG_MASK | 1)) == W_TAG_STRINGSYM) &&
        ((needle_v & (W_TAG_MASK | 1)) == W_TAG_STRINGSYM)) {
        size_t rmode = (size_t)((recv >> 1) & 7);
        size_t nmode = (size_t)((needle_v >> 1) & 7);
        if (__builtin_expect(rmode >= 6 && nmode >= 6, 1)) {
            const char *str;
            size_t str_len;
            if (rmode == 7) {
                WString *ws = w_as_heap_str(recv);
                str = ws->data;
                str_len = w_heap_string_len(ws);
            } else {
                const uint8_t *slot = g_string_slab.base + ((size_t)((recv >> 4) & 0xFFFFFF) << 5);
                str = (const char *)(slot + W_SLAB_DATA_OFFSET);
                str_len = (size_t)((recv >> 28) & 0x3F);
                if (!str_len) str_len = slot[1];
            }
            const char *needle;
            size_t needle_len;
            if (nmode == 7) {
                WString *nws = w_as_heap_str(needle_v);
                needle = nws->data;
                needle_len = w_heap_string_len(nws);
            } else {
                const uint8_t *nslot = g_string_slab.base + ((size_t)((needle_v >> 4) & 0xFFFFFF) << 5);
                needle = (const char *)(nslot + W_SLAB_DATA_OFFSET);
                needle_len = (size_t)((needle_v >> 28) & 0x3F);
                if (!needle_len) needle_len = nslot[1];
            }
            const char *found = w_mem_search(str, str_len, needle, needle_len);
            return found ? (W_TAG_INT | ((uint64_t)(found - str) & W_PAYLOAD_MASK)) : W_NIL;
        }
        if (rmode <= 5 && nmode <= 5) {
            if (nmode == 0) return W_TAG_INT;
            if (nmode > rmode) return W_NIL;
            uint64_t r_pay = recv >> 4;
            uint64_t mask = (1ULL << (8 * nmode)) - 1;
            uint64_t n_pay = (needle_v >> 4) & mask;
            for (size_t i = 0; i <= rmode - nmode; i++) {
                if (((r_pay >> (8 * i)) & mask) == n_pay)
                    return W_TAG_INT | (uint64_t)i;
            }
            return W_NIL;
        }
    }
    if (w_is_rope(recv)) recv = w_rope_flatten(recv);
    char _sbuf[6];
    const char *str;
    size_t str_len;
    w_str_data(recv, _sbuf, &str, &str_len);
    char _nbuf[6];
    const char *needle;
    size_t needle_len;
    w_str_data(needle_v, _nbuf, &needle, &needle_len);
    size_t offset = 0;
    if (offset_v != W_NIL) {
        int64_t off = w_as_int(offset_v);
        if (off < 0 || (size_t)off > str_len) return W_NIL;
        offset = (size_t)off;
    }
    if (needle_len == 0) return w_int((int64_t)offset);
    const char *found = w_mem_search(str + offset, str_len - offset, needle, needle_len);
    if (found) return w_int((int64_t)(found - str));
    return W_NIL;
}

/* Last occurrence of needle, mirroring w_string_index. Optional pos_v
 * caps the highest start index considered (Ruby rindex semantics). */
WValue w_string_rindex(WValue recv, WValue needle_v, WValue pos_v) {
    if (w_is_rope(recv)) recv = w_rope_flatten(recv);
    char _sbuf[6];
    const char *str;
    size_t str_len;
    w_str_data(recv, _sbuf, &str, &str_len);
    char _nbuf[6];
    const char *needle;
    size_t needle_len;
    w_str_data(needle_v, _nbuf, &needle, &needle_len);
    size_t limit = str_len;
    if (pos_v != W_NIL) {
        int64_t pos = w_as_int(pos_v);
        if (pos < 0) return W_NIL;
        if ((size_t)pos < limit) limit = (size_t)pos;
    }
    if (needle_len == 0) return w_int((int64_t)limit);
    if (needle_len > str_len) return W_NIL;
    size_t hay_len = str_len;
    if (limit < str_len - needle_len) hay_len = limit + needle_len;
    int64_t found = w_mem_rsearch(str, hay_len, needle, needle_len);
    return found >= 0 ? w_int(found) : W_NIL;
}

WValue w_string_repeat(WValue recv, WValue count_v) {
    if (w_is_rope(recv)) recv = w_rope_flatten(recv);
    char _sbuf[6];
    const char *str;
    size_t str_len;
    w_str_data(recv, _sbuf, &str, &str_len);
    int64_t n = w_as_int(count_v);
    if (n < 0) die("repeat count must be non-negative");
    if (n == 0 || str_len == 0) return w_string("");
    if ((uint64_t)n > W_STRING_LEN_MASK / str_len)
        die("string exceeds 31-bit byte length limit");
    size_t total = str_len * (size_t)n;
    if (total <= 5) {
        char tmp[6];
        for (size_t i = 0; i < total; i++) tmp[i] = str[i % str_len];
        tmp[total] = '\0';
        return w_box_inline_str(tmp, total);
    }
    /* Allocate WString directly — skip interning for large results */
    WString *ws = malloc(sizeof(WString) + total + 1);
    w_heap_string_set_meta(ws, (uint32_t)total, w_string_ascii_p(recv));
    memcpy(ws->data, str, str_len);
    /* Doubling copy: O(log n) memcpy calls instead of O(n) */
    size_t copied = str_len;
    while (copied < total) {
        size_t chunk = copied;
        if (chunk > total - copied) chunk = total - copied;
        memcpy(ws->data + copied, ws->data, chunk);
        copied += chunk;
    }
    ws->data[total] = '\0';
    return w_box_heap_str(ws);
}

static _Atomic int w_dispatch_ready = 0;
static pthread_once_t w_dispatch_once = PTHREAD_ONCE_INIT;

static void w_dispatch_init_once(void) {
    w_init_method_names();
    w_init_ic_tables();
    atomic_store_explicit(&w_dispatch_ready, 1, memory_order_release);
}

static void w_dispatch_init(void) {
    pthread_once(&w_dispatch_once, w_dispatch_init_once);
}

static WValue w_method_dispatch(WValue recv, WValue name, WArray *args, WValue args_arr) {
    (void)args_arr;
    if (__builtin_expect(!atomic_load_explicit(&w_dispatch_ready, memory_order_acquire), 0))
        w_dispatch_init();

    /* Packed WIRE records preserve the compiler's hash-style field API while
     * storing the instruction itself in the bump arena. Keep this ahead of
     * generic type-class dispatch: []/[]= are representation primitives, not
     * user-overridable language methods. */
    if (w_is_wire(recv)) {
        if (name == WN_idx && args->size == 1) {
            WValue key = args->slots[args->start];
            if (w_is_wire_sequence(recv)) {
                if (!w_is_int(key)) return W_NIL;
                return w_wire_sequence_get(recv, w_as_int(key));
            }
            WValue value = w_wire_field_load(recv, key);
            return value == W_UNDEF ? W_NIL : value;
        }
        if (name == WN_idxset && args->size == 2) {
            if (w_is_wire_sequence(recv)) {
                WValue key = args->slots[args->start];
                if (!w_is_int(key)) die("WIRE sequence index must be an Int");
                return w_wire_sequence_set(recv, w_as_int(key),
                                           args->slots[args->start + 1]);
            }
            return w_wire_field_store(recv, args->slots[args->start],
                                      args->slots[args->start + 1]);
        }
        if (name == WN_size && args->size == 0 && w_is_wire_sequence(recv))
            return w_int(w_wire_sequence_size(recv));
    }

    /* Rope: flatten and dispatch as string */
    if (w_is_rope(recv)) recv = w_rope_flatten(recv);

    /* Closures dispatch .call(args...) → invoke the closure */
    if (w_is_closure(recv) && name == WN_call) {
        if (args->size == 0) return w_closure_call_0(recv);
        if (args->size == 1) return w_closure_call_1(recv, args->slots[0]);
        if (args->size == 2) return w_closure_call_2(recv, args->slots[0], args->slots[1]);
        if (args->size == 3) return w_closure_call_3(recv, args->slots[0], args->slots[1], args->slots[2]);
        if (args->size == 4) return w_closure_call_4(recv, args->slots[0], args->slots[1], args->slots[2], args->slots[3]);
        die("closure .call supports up to 4 arguments");
    }

    if (w_is_array(recv)) {
        WValue result = w_try_type_class_dispatch(recv, name, args);
        if (result != W_UNDEF) return result;
    }

    /* Try IC table for migrated builtins. Lets w_method_call /
     * w_method_call_fast (which bypass the cached fast path) reach the
     * IC handlers without falling through to a stale cascade entry. */
    {
        uint64_t key = w_dispatch_key(recv);
        const WICEntry *row = w_resolve_ic(key, name, recv);
        if (row) {
            w_check_builtin_arity(key, name, row, args->size);
            return row->fn(recv, args->slots, args->size);
        }
    }

    /* Array storage and numeric kernels live in w_ic_array_table. Header and
     * endpoint query leaves live in core/array.w; collection combinators
     * resolve through Enumerable. */

    /* Hash size, has_key?, keys, values, merge!, each, delete, get/idx, and
     * set/idxset live in w_ic_hash_table. Hash#map comes from Enumerable. */

    /* String/Symbol storage primitives (idx, case conversion,
     * UTF-8/parse/convert, =~, match?, etc.) remain in w_ic_string_table.
     * size, length, and empty? fall through to their Tungsten class. */

    /* Regex, Int.times, Socket, retained Mmap primitives, Atomic
     * cas/get/set/add, Channel send/close, and Thread join/kill use ICs.
     * The four bounded synchronization leaves fall through to core sources. */

    /* ByteArray method dispatch removed — ByteArray is a
     * WArray<u8>. Header query leaves reach Array's Tungsten type class;
     * get/set/idx/idxset/copy/etc. use the standard array IC above.
     * WN_concat is likewise handled by the type-class table. */

    /* BoolArray dispatch removed — BoolArray is a WArray<u1>.
     * Query leaves reach Array's Tungsten type class; idx/idxset/each retain
     * the standard array path, whose ebits=1 cases convert bits ↔ Bool. */

    /* BigArray (key 0x92) and SmallArray (key 0x09) inline fast
     * paths live in their IC tables. Methods not in IC fall through here;
     * the global type-class dispatch at the bottom catches user-defined
     * trait methods (each, map, etc. from core/big_array.w / small_array.w). */

    /* Typed-array storage/mutation methods (fill, view,
     * slice_view, data, raw_ptr, push, pop, shift, unshift, idx, idxset,
     * get, set, min, max, sum, fastsum, sumsq, dot, cross, scale, scale!,
     * cos, sin, sqrt, matvec_i8, matmul_i8, sort) live in the Array IC.
     * size/cap/empty?/first/last fall through to core/array.w. */

    /* Per-kind node dispatch: packed AST nodes route to their specialized
     * class via g_node_kind_class[kind]. w_type_class_dispatch walks the
     * Call→Node (etc.) superclass chain, so shared accessors on Node are
     * found through inheritance. */
    if (w_is_node(recv)) {
        uint16_t cid_slot = g_node_kind_class[w_node_kind(recv) & 0xFF];
        if (cid_slot) {
            WValue result = w_type_class_dispatch(cid_slot - 1, recv, name, args);
            if (result != W_UNDEF) return result;
        }
    }

    /* Type class dispatch: check if any Tungsten class is registered for this dispatch key */
    if (w_is_bytes(recv) && g_byte_array_class) {
        WValue result = w_type_class_dispatch(g_byte_array_class - 1, recv, name, args);
        if (result != W_UNDEF) return result;
    }
    {
        uint64_t key = w_dispatch_key(recv);
        if (key < 256) {
            uint16_t cid_slot = g_type_class[key];
            if (cid_slot) {
                WValue result = w_type_class_dispatch(cid_slot - 1, recv, name, args);
                if (result != W_UNDEF) return result;
            }
        }
    }

    /* Object method dispatch */
    if (w_is_instance(recv)) {
        WObject *obj = as_object(recv);
        WMethod *m = w_method_lookup_arity(g_class_table[obj->class_id], name, args->size + 1);
        if (!m) m = w_method_lookup(g_class_table[obj->class_id], name);
        if (m) {
            /* Pad missing args with W_NIL (default parameters) and dispatch
             * based on declared arity, not caller-provided arg count. */
            int expected = m->arity - 1; /* subtract self */
            /* Implicit construction from the receiver's class: a one-param
             * method called with N>1 args builds its argument from the
             * receiver's own class when the constructor arity matches —
             * p.distance(2, 3, 4) â¡ p.distance(Point.new(2, 3, 4)). */
            /* A `*rest` parameter already takes every argument (the Ruby
             * implementation's rule), so it never wraps them. */
            if (expected == 1 && args->size > 1 && m->splat_index_plus_one == 0) {
                WClass *k = g_class_table[obj->class_id];
                if (w_method_lookup_arity(k, WN_new, args->size + 1)) {
                    WValue cls = w_box_ptr(k, W_SUBTAG_CLASS);
                    WValue inst = w_method_dispatch(cls, WN_new, args, args_arr);
                    typedef WValue (*ic_fn1)(WValue, WValue);
                    return ((ic_fn1)m->fn_ptr)(recv, inst);
                }
            }
            return w_method_invoke(m, recv, args->slots, args->size);
        }
        if (name == WN_to_s) {
            w_check_universal_arity(name, args->size, 0, 0);
            return w_to_s(recv);
        }
    }

    /* Class method dispatch */
    if (w_is_class(recv)) {
        WClass *klass = as_class(recv);

#ifndef TUNGSTEN_RUNTIME_COMPILER_IMAGE
        /* Socket.listen(host, port, backlog) */
        if (strcmp(klass->name, "Socket") == 0 && w_hash_key_eq(name, WN_listen)) {
            if (args->size < 2) die("Socket.listen requires at least host and port");
            const char *host = as_str(args->slots[0]);
            int port = (int)w_as_int(args->slots[1]);
            int backlog = (args->size > 2) ? (int)w_as_int(args->slots[2]) : 128;
            return w_socket_tcp_listen(host, port, backlog);
        }

        /* Socket.connect(host, port) */
        if (strcmp(klass->name, "Socket") == 0 && w_hash_key_eq(name, WN_connect)) {
            if (args->size < 2) die("Socket.connect requires host and port");
            const char *host = as_str(args->slots[0]);
            int port = (int)w_as_int(args->slots[1]);
            return w_socket_tcp_connect(host, port);
        }

        /* TLS.init() / TLS.load_cert(cert, key) */
        if (strcmp(klass->name, "TLS") == 0) {
            if (w_hash_key_eq(name, WN_init)) {
                return w_tls_init();
            }
            if (w_hash_key_eq(name, WN_load_cert)) {
                if (args->size < 2) die("TLS.load_cert requires cert_path and key_path");
                const char *cert = as_str(args->slots[0]);
                const char *key = as_str(args->slots[1]);
                return w_tls_load_cert(cert, key);
            }
            if (w_hash_key_eq(name, WN_client_wrap)) {
                if (args->size < 2) die("TLS.client_wrap requires socket and hostname");
                return w_tls_client_wrap(args->slots[0], as_str(args->slots[1]));
            }
        }

        /* Response.new(status, body) — fast path avoids strlen by using the stored byte length.
           User-defined classes named Response still need normal constructor dispatch. */
        if (strcmp(klass->name, "Response") == 0 && w_hash_key_eq(name, WN_new) &&
            w_method_lookup(klass, WN_new) == NULL) {
            if (args->size < 2) die("Response.new requires status and body");
            return w_response_new_wv(args->slots[0], args->slots[1]);
        }
#endif


        /* ByteArray.new(length_or_array) */
        if (strcmp(klass->name, "ByteArray") == 0 && w_hash_key_eq(name, WN_new)) {
            if (args->size > 0 && w_is_array(args->slots[0])) {
                WArray *src = w_as_array(args->slots[0]);
                WValue out = w_bytes_new(src->size);
                uint8_t *dst = (uint8_t *)w_as_array(out)->slots;
                for (int32_t bi = 0; bi < src->size; bi++) {
                    WValue elem = w_array_get(args->slots[0], w_int(bi));
                    dst[bi] = (uint8_t)(w_to_i64(elem) & 0xFF);
                }
                return out;
            }
            int64_t len = (args->size > 0) ? w_as_int(args->slots[0]) : 0;
            return w_bytes_new(len);
        }

        /* Array.new(size = 0, fill = nil). Repeating the same WValue is
         * deliberate: mutable fill objects alias exactly as the source-level
         * constructor contract requires. */
        if (strcmp(klass->name, "Array") == 0 && w_hash_key_eq(name, WN_new)) {
            if (args->size > 2)
                w_raise(w_string("Array.new expects zero, one, or two arguments"));
            WValue size = args->size > 0 ? args->slots[0] : w_int(0);
            WValue fill = args->size > 1 ? args->slots[1] : W_NIL;
            return w_array_new_filled(size, fill);
        }

        /* SmallArray.new(:element_type, size). The boxed helper accepts both
         * literal and dynamically supplied element-type symbols. */
        if (strcmp(klass->name, "SmallArray") == 0 && w_hash_key_eq(name, WN_new)) {
            if (args->size != 2)
                w_raise(w_string("SmallArray.new expects element type and size"));
            return w_small_array_new_value(args->slots[0], args->slots[1]);
        }

        /* BoolArray.new(length) — returns a bit-packed WArray<u1> */
        if (strcmp(klass->name, "BoolArray") == 0 && w_hash_key_eq(name, WN_new)) {
            int64_t len = (args->size > 0) ? w_as_int(args->slots[0]) : 0;
            return w_bool_array_new(len);
        }

        /* Packed Date construction. Known `Date.new` calls inline the Core
         * class method; this arm preserves the same contract when the class
         * receiver is erased and dispatch reaches the runtime. */
        if (strcmp(klass->name, "Date") == 0 && w_hash_key_eq(name, WN_new)) {
            if (args->size < 1 || args->size > 7) {
                w_raise(w_string("Date.new expects one to seven arguments"));
                return W_NIL;
            }
            WValue defaults[] = {w_int(1), w_int(1), w_int(0), w_int(0),
                                 w_int(0), w_int(0)};
            WValue fields[7];
            fields[0] = args->slots[0];
            for (int i = 1; i < 7; i++)
                fields[i] = i < args->size ? args->slots[i] : defaults[i - 1];
            return w_date_new_w(fields[0], fields[1], fields[2], fields[3],
                                fields[4], fields[5], fields[6]);
        }

        /* Packed Decimal values cannot be represented by the generic WObject
         * allocator. Keep implicit construction rejected until Decimal owns a
         * scalar constructor contract. */
        if (strcmp(klass->name, "Decimal") == 0 && w_hash_key_eq(name, WN_new)) {
            w_raise(w_string("Decimal.new is not a supported scalar constructor; "
                             "use a decimal literal or String#to_d"));
        }

        /* Rational.new(numerator, denominator = 1) returns the packed scalar,
         * not an allocated WObject instance. */
        if (strcmp(klass->name, "Rational") == 0 && w_hash_key_eq(name, WN_new)) {
            if (args->size < 1 || args->size > 2)
                w_raise(w_string("Rational.new expects one or two arguments"));
            WValue denominator = args->size == 2 ? args->slots[1] : w_int(1);
            return w_rational_new(args->slots[0], denominator);
        }

        /* A source static `.new` is a representation-level factory. Direct
         * class calls and the interpreter already give it priority over the
         * generic allocate-then-initialize protocol; preserve that ordering
         * when the class receiver has been erased too. Builtin class
         * primitives above retain their documented precedence. */
        WMethod *sm = NULL;
        if (w_hash_key_eq(name, WN_new)) {
            sm = w_static_method_lookup_arity(klass, name, args->size + 1);
            if (!sm) sm = w_static_method_lookup(klass, name);
            if (sm) goto invoke_static_method;

            WValue obj = w_object_new(recv);
            WMethod *m = w_method_lookup_arity(klass, WN_new, args->size + 1);
            if (!m) m = w_method_lookup(klass, WN_new);
            if (m) {
                w_method_invoke(m, obj, args->slots, args->size);
            } else if (args->size > 0) {
                /* No constructor accepts these arguments. Dropping them
                 * silently returned an object with every field unset, so the
                 * mistake surfaced far away as a nil field read. Tungsten's
                 * constructor is `-> new(...)` (spec 5.3.1): `init` and
                 * `initialize` are ordinary methods that `.new` never calls,
                 * and a `ro`/`field` declaration does not generate one, so
                 * name the required form rather than just the arity. */
                /* w_raise, not die: this is a user programming error, so it
                 * must be catchable by begin/rescue like the neighbouring
                 * constructor diagnostics. */
                char cbuf[512];
                snprintf(cbuf, sizeof cbuf,
                         "%s.new: no constructor accepts %d argument%s. Define "
                         "`-> new(@field)` on %s -- `init`/`initialize` are not "
                         "constructor hooks in Tungsten, and `ro :field` / "
                         "`- data` declarations do not generate a constructor.",
                         klass->name, args->size, args->size == 1 ? "" : "s",
                         klass->name);
                w_raise(w_string(cbuf));
            }
            /* Publish-on-exit: init already ran, so any nested `.new` it
             * performed has been and gone — this assignment makes the
             * OUTERMOST selection the one w_method_call_slow observes. */
            g_generic_ctor_selected = m;
            g_generic_ctor_recv = recv;
            return obj;
        }

        /* User-defined class (static) methods.
         * Arity includes __self (the class object), so user-visible param count = arity - 1.
         * Pass recv (the class WValue) as the first argument. */
        sm = w_static_method_lookup_arity(klass, name, args->size + 1);
        if (!sm) sm = w_static_method_lookup(klass, name);
invoke_static_method:
        if (sm) {
            return w_method_invoke(sm, recv, args->slots, args->size);
        }
    }

    /* StringBuffer primitives live in w_ic_strbuf_table. Source lowering can
     * still specialize known receivers, while erased receivers use the same
     * byte-exact operations through the inline cache. */

    /* Universal to_s fallback for any type */
    if (name == WN_to_s) {
        w_check_universal_arity(name, args->size, 0, 0);
        return w_to_s(recv);
    }

    /* Universal public hash fallback. User-defined `hash` methods and typed
     * source methods win through normal lookup above; builtin containers use
     * the structural algorithm while hash-table keys keep identity hashing. */
    if (name == WN_hash) {
        w_check_universal_arity(name, args->size, 0, 0);
        return w_public_hash(recv);
    }

    /* nil? is available even when Object's source methods were not loaded.
     * Test the value tag directly, independently of user-defined equality. */
    if (w_hash_key_eq(name, WN_nil_q)) {
        w_check_universal_arity(name, args->size, 0, 0);
        return w_bool(w_is_nil(recv));
    }

    /* Middle-dot multiply (mÂ·cÂ²): Â· on numeric-domain receivers is
     * multiplication. Vec/Mat classes define their own Â· (dot product),
     * which wins via normal class dispatch before this universal arm. */
    if (args->size >= 1) {
        const char *nm = as_str(name);
        if (nm[0] == (char)0xC2 && nm[1] == (char)0xB7 && nm[2] == 0 &&
            (w_is_int(recv) || w_is_double(recv) || w_is_numeric_tag(recv) || w_is_domain_obj(recv))) {
            w_check_universal_arity(name, args->size, 1, 1);
            return w_mul(recv, args->slots[0]);
        }
    }

    /* Universal respond_to? — reflective method-existence check. Declared
     * bodyless in core/object.w so the runtime supplies it (the hypercomplex
     * tower's scalar_like? relies on it: `!@1.respond_to?("components")`).
     * Instances consult their class's instance methods (walking inheritance);
     * classes consult static methods; builtin-typed receivers answer false. */
    if (w_hash_key_eq(name, WN_respond_to_q) && args->size >= 1) {
        w_check_universal_arity(name, args->size, 1, 1);
        WValue mname = args->slots[0];
        if (w_is_instance(recv))
            return w_bool(w_method_lookup(g_class_table[((WObject *)w_as_ptr(recv))->class_id], mname) != NULL);
        if (w_is_class(recv))
            return w_bool(w_static_method_lookup((WClass *)w_as_ptr(recv), mname) != NULL);
        return w_bool(0);
    }

    /* Universal spaceship: a <=> b → -1/0/1 (nil if incomparable). Backs
     * Comparable for the builtin ordered types (Integer/BigInt/Float/
     * Decimal/Char/Instant/String). User instances that define their own
     * <=> are dispatched by the normal method lookup below, before this is
     * reached — this only rescues builtin receivers that would otherwise
     * hit "undefined method '<=>'". */
    if (w_hash_key_eq(name, WN_spaceship) && args->size >= 1
        && !w_is_instance(recv) && !w_is_class(recv)) {
        w_check_universal_arity(name, args->size, 1, 1);
        return w_spaceship(recv, args->slots[0]);
    }

    /* Universal is_a?(class) — instance ancestry walk (an instance is_a? its
     * class and every superclass); primitives compare by builtin type name.
     * Backs the synthesized operator-overload dispatcher and is useful on its
     * own. A non-class argument or unrelated receiver answers false. */
    if (w_hash_key_eq(name, WN_is_a_q) && args->size >= 1) {
        w_check_universal_arity(name, args->size, 1, 1);
        return w_value_is_a(recv, args->slots[0]);
    }

    const char *type_name =
        w_is_int(recv) ? "Int" :
        w_is_double(recv) ? "Float" :
        w_is_string(recv) ? "String" :
        w_is_symbol(recv) ? "Symbol" :
        w_is_array(recv) ? "Array" :
        w_is_bool(recv) ? "Boolean" :
        w_is_nil(recv) ? "nil" :
        w_is_channel(recv) ? "Channel" :
        w_is_socket(recv) ? "Socket" :
        w_is_bytes(recv) ? "ByteArray" :
        w_is_strbuf(recv) ? "StringBuffer" :
        w_is_instance(recv) ? g_class_table[((WObject *)w_as_ptr(recv))->class_id]->name :
        w_is_class(recv) ? ((WClass *)w_as_ptr(recv))->name : "Object";
    /* Render integer receivers by value — "for 1" reads better than
     * "for Int", and the raw bits after it still carry the tag. */
    char int_desc[24];
    if (w_is_int(recv)) {
        snprintf(int_desc, sizeof int_desc, "%lld", (long long)w_as_int(recv));
        type_name = int_desc;
    }
    /* Optimized binaries can't resolve this dispatch site by PC (see
     * __w_ic_site); recover its exact source location from the IC slot
     * recorded by the slow path so the error header and innermost frame
     * still carry file:line:col. */
    {
        const WIcSite *site = w_resolve_ic_site(g_last_miss_slot);
        if (site) __w_loc_set_col(site->file, site->line, site->col);
    }
    {
        char nm_buf[256];
        snprintf(nm_buf, sizeof(nm_buf), "undefined method '%s' for %s (%s 0x%llx)",
                 as_str(name), type_name, w_type_label(recv), (unsigned long long)recv);
        die_as("NoMethodError", nm_buf);
    }
    return W_NIL;
}

/* Release a WValue if it's a heap-allocated type. Safe to call on any value.
 * Frees mode-7 heap strings, arrays, hashes, string buffers, closures and
 * unfrozen source-class instances, and returns bounded-size BigInt boxes to
 * the thread-local capacity recycler.
 * Bigints: a single calloc (limbs are a flexible array member, see
 * bigint_alloc) and never interned — every bigint_from_* mints or takes a
 * distinct allocation, so releasing a provably-dead box is safe. The compiler emits
 * this for call-argument temps it boxed itself (raw machine int >48 bits
 * boxed via w_int for a typed callee that unboxes on entry); without it,
 * every such call leaked one WBigint (75 MB/s in the 49-bit-mask
 * flip-graph walkers, 2026-07-02). */
/* Release for loop-carried integers (compiler/lib/ownership.w,
 * loop_carried_releases).  At the end of a loop iteration the compiler hands
 * over the previous loop value `prev` and up to two intermediates of the
 * iteration's arithmetic, all proven not to escape: they reach only integer
 * arithmetic helpers, comparisons, and the loop phi.  `init` is the value the
 * loop was entered with (possibly borrowed from the caller) and `next` the
 * value that survives into the next iteration.
 *
 * Every value must be an integer: a non-integer result (Rational, Complex,
 * Decimal, ...) of `+`, `*`, ... may hold an operand inside it, so the whole
 * release is skipped then.  Only BigInts own storage.  A value equal to
 * `init`, `next`, `prev` or an earlier intermediate is skipped: identical
 * words are one allocation, and identity results of BigInt arithmetic carry
 * a shared count, so releasing a distinct alias only drops that count. */
void w_value_release_loop(int64_t extra, WValue init, WValue prev, WValue next,
                          WValue t1, WValue t2) {
    if (extra < 0 || extra > 2) return;
    if (!w_is_integer_any(prev) || !w_is_integer_any(next)) return;
    if (extra >= 1 && !w_is_integer_any(t1)) return;
    if (extra >= 2 && !w_is_integer_any(t2)) return;
    if (extra >= 1 && w_is_bigint(t1) && t1 != init && t1 != next && t1 != prev)
        bigint_release_if_live(w_as_bigint(t1));
    if (extra >= 2 && w_is_bigint(t2) && t2 != init && t2 != next && t2 != prev && t2 != t1)
        bigint_release_if_live(w_as_bigint(t2));
    if (w_is_bigint(prev) && prev != init && prev != next)
        bigint_release_if_live(w_as_bigint(prev));
}

/* Compiler-emitted (ownership.w, int_temp_releases) after the last use of an
 * integer temporary: `t` is the result of an integer-arithmetic helper (or of
 * a function int_fresh_returns proved returns one), and
 * every use of it reads it without keeping it.  Integer arithmetic never
 * retains an operand (it returns a fresh value, an inline integer, or the
 * operand with its BigInt shared count raised), but other kinds can: a
 * Rational may hold a BigInt numerator, a user operator may return an
 * unmarked alias.  So `t` is released only when it and each of the `n`
 * witnesses (the operands that produced `t` and the other operands of the
 * operations that read it) are integers.  The inline wrapper
 * __w_int_temp_release reaches this only for a BigInt `t`. */
void w_int_temp_release(int64_t n, WValue t, WValue w1, WValue w2, WValue w3) {
    if (!w_is_bigint(t) || n < 0 || n > 3) return;
    /* A witness that is `t` itself is a call result that may be the very
     * argument handed back unmarked: then nothing is dead. */
    if (n >= 1 && (w1 == t || !w_is_integer_any(w1))) return;
    if (n >= 2 && (w2 == t || !w_is_integer_any(w2))) return;
    if (n >= 3 && (w3 == t || !w_is_integer_any(w3))) return;
    bigint_release_if_live(w_as_bigint(t));
}

/* Compiler-emitted (ownership.w, int_fresh_returns) right after an
 * arithmetic result that a fresh-returning function returns.  With integer
 * operands it is fresh or an operand already marked shared; otherwise a
 * user operator may have handed back an alias it never marked, so a BigInt
 * result gets a shared mark and a caller's release only drops it. */
void w_int_result_seal(WValue r, WValue a, WValue b) {
    if (!w_is_bigint(r)) return;
    if (w_is_integer_any(a) && w_is_integer_any(b)) return;
    w_bigint_mark_shared(w_as_bigint(r));
}

/* Compiler-emitted (ownership.w, owned_slot_releases) after a call that read
 * a slot-held integer `v` and returned `r`: when `r` may still hold `v` -- it
 * is `v` itself, possibly unmarked, or a non-integer that can contain it --
 * `v` gets a shared mark, so the slot's later release only drops it. */
void w_int_alias_seal(WValue v, WValue r) {
    if (!w_is_bigint(v)) return;
    if (r != v && w_is_integer_any(r)) return;
    w_bigint_mark_shared(w_as_bigint(v));
}

void w_value_free(WValue v) {
    if (w_is_bigint(v)) {
        bigint_release_if_live(w_as_bigint(v));
        return;
    }
    if (w_is_heap_str(v)) {
        WString *ws = w_as_heap_str(v);
        /* Park small blocks for the decimal formatters instead of freeing:
         * see w_string_small_fresh.  One slot per thread; an occupied slot
         * means a plain free, so this is at most a TLS load + two compares
         * on the non-parking path. */
        if (w_str_park == NULL && w_heap_string_len(ws) <= W_STR_PARK_MAX) {
            w_str_park = ws;
            w_str_park_cap = w_heap_string_len(ws);
            return;
        }
        free(ws);
        return;
    }
    /* Array (W_SUBTAG_ARRAY). w_array_new mints calloc(WArray) + calloc(slots)
     * with flags=W_FLAG_OWNED — a fresh, unaliased allocation the compiler
     * hands us only when escape analysis proved it dead. The `slots` pointer,
     * however, is BORROWED for several array shapes and must not be free()d:
     *   - W_FLAG_VIEW         → slots aliases another array's buffer
     *   - W_FLAG_PAGE_ALIGNED → slots is an mmap region (needs munmap, not free)
     *   - W_FLAG_BIG          → BigArray-tier layout; different lifetime/struct
     *   - W_FLAG_POOLED       → the array is live in a recycle pool (g_array_*);
     *                           freeing it would corrupt the pool. Skip entirely.
     * So: bail on POOLED/BIG; release owned standalone slots with free or
     * munmap according to their allocation flag, then free the header. */
    if (w_is_array(v)) {
        WArray *arr = w_as_array(v);
        uint8_t fl = arr->flags;
        if (fl & (W_FLAG_POOLED | W_FLAG_BIG)) return;
        if (w_rt_array_has_views(v)) return;
        if (fl == W_FLAG_OWNED && w_arr_park == NULL && arr->cap <= W_ARR_PARK_MAX_CAP) {
            w_arr_park = arr;
            return;
        }
        w_rt_array_release_slots(arr->slots, arr->ebits, arr->cap, fl);
        free(arr);
        return;
    }
    /* Hash (W_SUBTAG_HASH). w_hash_new calloc's the WHash plus ONE storage
     * block (w_hash_allocate_storage) whose base is keys — freeing keys
     * frees values and index with it; both are private to the hash. Freed WValues inside are NOT recursed into — they may be live
     * elsewhere, exactly like closure captures below. Bail when the pool
     * still holds it (W_HASH_FLAG_POOLED) or it was frozen for sharing.
     * History: this branch was a deliberate no-op for a while — the
     * ownership pass marked a constructor-stored hash non-escaped
     * (:ivar_set_idx had no mark_escapes arm) and freeing it was a UAF.
     * That hole and its siblings (:phi_i64, :store_cvar, view/inline
     * container stores, cleanup/recycle pushes) are closed in
     * compiler/lib/ownership.w, gated by spec/compiler/
     * hash_free_escape_spec.w + ownership_phi_escape_spec.w and the
     * stage-2 self-host. */
    if (w_is_hash(v)) {
        WHash *h = (WHash *)w_as_ptr(v);
        if (h->flags & (W_HASH_FLAG_POOLED | W_HASH_FLAG_FROZEN)) return;
        free(h->keys);  /* storage-block base: values and index live inside */
        free(h);
        return;
    }
    /* StringBuffer (W_SUBTAG_STRBUF). w_strbuf_new / w_strbuf_recycle_or_new
     * malloc(WStrBuf) + malloc(data); `data` is always a private heap buffer
     * (append reallocs it in place). Never free one parked in the recycle pool
     * (W_POOL_FLAG_POOLED) — the pool still holds it. */
    if (w_is_strbuf(v)) {
        WStrBuf *sb = (WStrBuf *)w_as_ptr(v);
        if (sb->flags & W_POOL_FLAG_POOLED) return;
        free(sb->data);
        free(sb);
        return;
    }
    /* Closure (W_SUBTAG_CLOSURE). w_closure_new calloc(WClosure) and, when it
     * has captures, calloc's a PRIVATE copy of the capture array (see
     * heap_caps). We free that array + the struct — but NOT the captured
     * WValues themselves: those may still be live elsewhere, and this function
     * never recurses. When capture_count == 0 the `captures` pointer is a
     * borrowed/NULL argument the closure never owns, so leave it. */
    if (w_is_closure(v)) {
        WClosure *cl = (WClosure *)w_as_ptr(v);
        if (cl->capture_count > 0) free(cl->captures);
        free(cl);
        return;
    }
    /* Source-class instance (W_SUBTAG_INSTANCE). w_object_new is ONE calloc —
     * header plus inline ivar slots — and nothing else ever owns the block,
     * so the header is the whole allocation. Ivar VALUES are not recursed
     * into: the compiler marked them escaped when the initializer stored
     * them, so they may be live elsewhere. The compiler hands an instance
     * here only when the guarded `Cls.new` construct arm produced it and
     * its initializer provably never stored `self` (ownership.w
     * construct_producer_class). A frozen instance was frozen for sharing
     * across goroutines — leave it alone, like the frozen-hash bail above. */
    if (w_is_instance(v)) {
        WObject *obj = (WObject *)w_as_ptr(v);
        if (obj->flags & (W_OBJ_FLAG_FROZEN | W_OBJ_FLAG_POOLED)) return;
        free(obj);
        return;
    }
}

WValue w_value_free_w(WValue v) {
    w_value_free(v);
    return W_NIL;
}

/* Convert raw i64 bits to a 16-character hex string WValue. */
WValue w_int_to_hex_str(uint64_t v) {
    char buf[17];
    static const char hex[] = "0123456789abcdef";
    for (int i = 15; i >= 0; i--) {
        buf[i] = hex[v & 0xF];
        v >>= 4;
    }
    buf[16] = '\0';
    return w_string_n_known_ascii(buf, 16, 1);
}


/* ---- Metal compute stubs (non-darwin platforms) ----
 * On macOS the real implementations live in runtime/metal.m; the
 * Makefile / build.rb compile that file alongside runtime.c and link
 * `-framework Metal -framework Foundation`. On every other platform
 * these stubs raise so any `core/metal.w` use surfaces the missing
 * dependency at the call site instead of a link error. The stubs are WEAK
 * and always compiled: when a program's IR references bridge symbols the
 * compile driver also passes metal.m/hid_bridge.m as sources, whose strong
 * definitions override these; otherwise the stubs stand in and the binary
 * links no GUI/GPU frameworks (faster cold start, leaner binaries). */
#define W_BRIDGE_STUB __attribute__((weak))
